import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64
PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.shared .align 2 .b16 smem_in[972];
.visible .entry conv3x3_bf16_nchw_no_bias(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 out_ptr,
    .param .u32 tot_elems
)
{
    .reg .pred %p0, %p1, %p2, %p3, %p4, %p5, %p6;
    .reg .u32 %tidx, %bid, %bdim, %gdim;
    .reg .u32 %tot;
    .reg .u64 %in, %wt, %out, %addr, %addr_w, %addr_o, %saddr, %sm_base;
    // constants and temporaries
    .reg .u32 %OW, %OH, %H, %W, %TILE, %HALO, %STR, %TILES_X, %TILES_Y, %TILES_PER, %TOTNOC;
    .reg .u32 %co_ohow, %ohow;
    .reg .u32 %N, %tot_tiles, %tile, %step;
    .reg .u32 %n, %oc, %ty, %tx, %rem1, %rem2;
    .reg .u32 %oyb, %oxb;
    .reg .u32 %tin_h, %tin_w, %tout_h, %tout_w, %tmp0, %tmp1, %tmp2, %tmp3, %tmp4, %tmp5, %tmp6, %tmp7, %tmp8;
    .reg .u32 %load_elems, %i, %c, %rem, %y, %x, %s, %gl_iy, %gl_ix;
    .reg .u32 %num_outs, %j, %yoff, %xoff;
    .reg .u32 %ic, %ky, %kx, %sm_index;
    .reg .f32 %acc, %vinf, %wf;
    .reg .b16 %in_b16, %w_b16, %out_b16;
    // Load params
    ld.param.u64 %in,  [in_ptr];
    ld.param.u64 %wt,  [wt_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u32 %tot, [tot_elems];
    // thread/block info
    mov.u32 %tidx, %tid.x;
    mov.u32 %bid,  %ctaid.x;
    mov.u32 %bdim, %ntid.x;
    mov.u32 %gdim, %nctaid.x;
    // shared memory base
     mov.u64 %sm_base, smem_in;
    // constants
    // ow = oh = 222, H = W = 224, TILE=16, HALO=2, STR=18, tiles_x=14, tiles_y=14
    mov.u32 %OW, 222;
    mov.u32 %OH, 222;
    mov.u32 %H,  224;
    mov.u32 %W,  224;
    mov.u32 %TILE, 16;
    mov.u32 %HALO, 2;
    mov.u32 %STR, 18;
    mov.u32 %TILES_X, 14;
    mov.u32 %TILES_Y, 14;
    // tiles_per_noc = 14 * 14 = 196; TOTNOC = 32 * 196 = 6272
    mov.u32 %TILES_PER, 196;
    mov.u32 %TOTNOC, 6272;
    // co_ohow = 32 * (222*222) = 1,577,088; ohow = 222*222
    mov.u32 %co_ohow, 1577088;
    mov.u32 %ohow,    49284;
    // N = tot / co_ohow
    div.u32 %N, %tot, %co_ohow;
    // tot_tiles = N * TOTNOC
    mul.lo.u32 %tot_tiles, %N, %TOTNOC;
    // CTA-stride over tiles
    mov.u32 %tile, %bid;
    mov.u32 %step, %gdim;
TILE_LOOP:
    setp.ge.u32 %p0, %tile, %tot_tiles;
    @%p0 bra DONE;
    // decode tile -> (n, oc, ty, tx)
    // n = tile / TOTNOC; rem1 = tile - n*TOTNOC
    div.u32 %n, %tile, %TOTNOC;
    mul.lo.u32 %tmp0, %n, %TOTNOC;
    sub.u32 %rem1, %tile, %tmp0;
    // oc = rem1 / TILES_PER; rem2 = rem1 - oc*TILES_PER
    div.u32 %oc, %rem1, %TILES_PER;
    mul.lo.u32 %tmp1, %oc, %TILES_PER;
    sub.u32 %rem2, %rem1, %tmp1;
    // ty = rem2 / TILES_X; tx = rem2 - ty*TILES_X
    div.u32 %ty, %rem2, %TILES_X;
    mul.lo.u32 %tmp2, %ty, %TILES_X;
    sub.u32 %tx, %rem2, %tmp2;
    // oyb = ty * TILE; oxb = tx * TILE
    mul.lo.u32 %oyb, %ty, %TILE;
    mul.lo.u32 %oxb, %tx, %TILE;
    // tile input height = min(H - oyb, TILE+HALO*1) = min(224 - oyb, 18)
    mov.u32 %tmp3, 224;
    sub.u32 %tmp3, %tmp3, %oyb;          // tmp3 = 224 - oyb
    setp.lt.u32 %p1, %tmp3, 18;
    selp.u32 %tin_h, %tmp3, 18, %p1;
    // tile input width = min(W - oxb, 18)
    mov.u32 %tmp4, 224;
    sub.u32 %tmp4, %tmp4, %oxb;          // tmp4 = 224 - oxb
    setp.lt.u32 %p2, %tmp4, 18;
    selp.u32 %tin_w, %tmp4, 18, %p2;
    // tile output height = min(OH - oyb, TILE) = min(222 - oyb, 16)
    mov.u32 %tmp5, 222;
    sub.u32 %tmp5, %tmp5, %oyb;          // tmp5 = 222 - oyb
    setp.lt.u32 %p3, %tmp5, 16;
    selp.u32 %tout_h, %tmp5, 16, %p3;
    // tile output width = min(OW - oxb, TILE) = min(222 - oxb, 16)
    mov.u32 %tmp6, 222;
    sub.u32 %tmp6, %tmp6, %oxb;          // tmp6 = 222 - oxb
    setp.lt.u32 %p4, %tmp6, 16;
    selp.u32 %tout_w, %tmp6, 16, %p4;
    // total elements to load into shared: 3 * tin_h * tin_w
    mul.lo.u32 %s, %tin_h, %tin_w;       // s = tin_h * tin_w
    mul.lo.u32 %load_elems, %s, 3;       // load_elems = 3*s
    // cooperative load of input tile into shared memory as bf16
    mov.u32 %i, %tidx;
L_LOAD:
    setp.ge.u32 %p5, %i, %load_elems;
    @%p5 bra L_LOAD_END;
    // c = i / s; rem = i - c*s
    div.u32 %c, %i, %s;
    mul.lo.u32 %tmp7, %c, %s;
    sub.u32 %rem, %i, %tmp7;
    // y = rem / tin_w; x = rem - y*tin_w
    div.u32 %y, %rem, %tin_w;
    mul.lo.u32 %tmp8, %y, %tin_w;
    sub.u32 %x, %rem, %tmp8;
    // global input coords
    add.u32 %gl_iy, %oyb, %y;
    add.u32 %gl_ix, %oxb, %x;
    // t2 = (((n*3 + c)*224 + gl_iy)*224 + gl_ix)
    mul.lo.u32 %tmp0, %n, 3;
    add.u32 %tmp0, %tmp0, %c;
    mul.lo.u32 %tmp0, %tmp0, 224;
    add.u32 %tmp0, %tmp0, %gl_iy;
    mul.lo.u32 %tmp0, %tmp0, 224;
    add.u32 %tmp0, %tmp0, %gl_ix;
    cvt.u64.u32 %addr, %tmp0;
    shl.b64 %addr, %addr, 1;
    add.u64 %addr, %in, %addr;
    ld.global.b16 %in_b16, [%addr];
    // smem index = c*324 + y*18 + x
    mul.lo.u32 %tmp1, %c, 324;
    mul.lo.u32 %tmp2, %y, 18;
    add.u32 %tmp2, %tmp2, %x;
    add.u32 %sm_index, %tmp1, %tmp2;
    cvt.u64.u32 %saddr, %sm_index;
    shl.b64 %saddr, %saddr, 1;
    add.u64 %saddr, %sm_base, %saddr;
    st.shared.b16 [%saddr], %in_b16;
    add.u32 %i, %i, %bdim;
    bra L_LOAD;
L_LOAD_END:
    bar.sync 0;
    // compute outputs within tile
    mul.lo.u32 %num_outs, %tout_h, %tout_w;
    mov.u32 %j, %tidx;
L_OUT:
    setp.ge.u32 %p6, %j, %num_outs;
    @%p6 bra L_OUT_END;
    // yoff = j / tout_w; xoff = j - yoff*tout_w
    div.u32 %yoff, %j, %tout_w;
    mul.lo.u32 %tmp0, %yoff, %tout_w;
    sub.u32 %xoff, %j, %tmp0;
    // acc = 0.0f
    mov.f32 %acc, 0f00000000;
    // ic loop
    mov.u32 %ic, 0;
L_IC:
    setp.ge.u32 %p1, %ic, 3;
    @%p1 bra L_IC_END;
    // ky loop
    mov.u32 %ky, 0;
L_KY:
    setp.ge.u32 %p2, %ky, 3;
    @%p2 bra L_KY_END;
    // kx loop
    mov.u32 %kx, 0;
L_KX:
    setp.ge.u32 %p3, %kx, 3;
    @%p3 bra L_KX_END;
    // smem index for input: ic*324 + (yoff+ky)*18 + (xoff+kx)
    add.u32 %tmp0, %yoff, %ky;
    mul.lo.u32 %tmp0, %tmp0, 18;
    add.u32 %tmp0, %tmp0, %xoff;
    add.u32 %tmp0, %tmp0, %kx;
    mul.lo.u32 %tmp1, %ic, 324;
    add.u32 %sm_index, %tmp0, %tmp1;
    cvt.u64.u32 %saddr, %sm_index;
    shl.b64 %saddr, %saddr, 1;
    add.u64 %saddr, %sm_base, %saddr;
    ld.shared.b16 %in_b16, [%saddr];
    cvt.rn.f32.bf16 %vinf, %in_b16;
    // weight index w2 = ((((oc)*3 + ic)*3 + ky)*3 + kx)
    mul.lo.u32 %tmp2, %oc, 3;
    add.u32 %tmp2, %tmp2, %ic;
    mul.lo.u32 %tmp2, %tmp2, 3;
    add.u32 %tmp2, %tmp2, %ky;
    mul.lo.u32 %tmp2, %tmp2, 3;
    add.u32 %tmp2, %tmp2, %kx;
    cvt.u64.u32 %addr_w, %tmp2;
    shl.b64 %addr_w, %addr_w, 1;
    add.u64 %addr_w, %wt, %addr_w;
    ld.global.b16 %w_b16, [%addr_w];
    cvt.rn.f32.bf16 %wf, %w_b16;
    fma.rn.f32 %acc, %vinf, %wf, %acc;
    // kx++
    add.u32 %kx, %kx, 1;
    bra L_KX;
L_KX_END:
    // ky++
    add.u32 %ky, %ky, 1;
    bra L_KY;
L_KY_END:
    // ic++
    add.u32 %ic, %ic, 1;
    bra L_IC;
L_IC_END:
    // store output
    add.u32 %tmp0, %oyb, %yoff;  // oy
    add.u32 %tmp1, %oxb, %xoff;  // ox
    // o2 = (((n*32 + oc)*222 + oy)*222 + ox)
    mul.lo.u32 %tmp2, %n, 32;
    add.u32 %tmp2, %tmp2, %oc;
    mul.lo.u32 %tmp2, %tmp2, 222;
    add.u32 %tmp2, %tmp2, %tmp0;
    mul.lo.u32 %tmp2, %tmp2, 222;
    add.u32 %tmp2, %tmp2, %tmp1;
    cvt.u64.u32 %addr_o, %tmp2;
    shl.b64 %addr_o, %addr_o, 1;
    add.u64 %addr_o, %out, %addr_o;
    cvt.rn.bf16.f32 %out_b16, %acc;
    st.global.b16 [%addr_o], %out_b16;
    // next output element for this thread
    add.u32 %j, %j, %bdim;
    bra L_OUT;
L_OUT_END:
    bar.sync 0;
    // next tile for this CTA
    add.u32 %tile, %tile, %step;
    bra TILE_LOOP;
DONE:
    ret;
}
"""
_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
