_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv3x3_bf16_nchw_no_bias")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3, bias=False, dtype=torch.bfloat16)

    def forward(self, x: torch.Tensor):
        assert x.dtype == torch.bfloat16
        N, C, H, W = x.shape
        oh = H - 2
        ow = W - 2
        y = torch.empty((N, 32, oh, ow), dtype=torch.bfloat16, device=x.device)

        tot = N * 32 * oh * ow
        block = 256
        grid_x = (tot + block - 1) // block

        module = _get_ptx_module()
        module.launch(
            "conv3x3_bf16_nchw_no_bias",
            grid=(grid_x, 1, 1),
            block=(block, 1, 1),
            arguments=[x, self.conv1.weight, y, i32(tot)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

